/**
 * The ASCII Bell character, which can be used to trigger a beep sound in the console.
 */
export const beep = "\u0007";

/**
 * An object containing ANSI escape codes for controlling the console cursor.
 */
export const cursor = {
  to(x: number, y?: number) {
    if (!y) {
      return `\x1B[${x + 1}G`;
    }

    return `\x1B[${y + 1};${x + 1}H`;
  },
  move(x: number, y: number) {
    let ret = "";

    if (x < 0) {
      ret += `\x1B[${-x}D`;
    } else if (x > 0) {
      ret += `\x1B[${x}C`;
    }

    if (y < 0) {
      ret += `\x1B[${-y}A`;
    } else if (y > 0) {
      ret += `\x1B[${y}B`;
    }

    return ret;
  },
  up: (count = 1) => `\x1B[${count}A`,
  down: (count = 1) => `\x1B[${count}B`,
  forward: (count = 1) => `\x1B[${count}C`,
  backward: (count = 1) => `\x1B[${count}D`,
  nextLine: (count = 1) => "\x1B[E".repeat(count),
  prevLine: (count = 1) => "\x1B[F".repeat(count),
  left: "\x1B[G",
  hide: "\x1B[?25l",
  show: "\x1B[?25h",
  save: "\x1B7",
  restore: "\x1B8"
};

/**
 * An object containing ANSI escape codes for erasing parts of the console.
 */
export const erase = {
  screen: "\x1B[2J",
  up: (count = 1) => "\x1B[1J".repeat(count),
  down: (count = 1) => "\x1B[J".repeat(count),
  line: "\x1B[2K",
  lineEnd: "\x1B[K",
  lineStart: "\x1B[1K",
  lines(count: number) {
    let lineClear = "";
    for (let i = 0; i < count; i++) {
      lineClear += this.line + (i < count - 1 ? cursor.up() : "");
    }

    if (count) {
      lineClear += cursor.left;
    }

    return lineClear;
  }
};

/**
 * An object containing ANSI escape codes for scrolling the console.
 */
export const scroll = {
  up: (count = 1) => "\x1B[S".repeat(count),
  down: (count = 1) => "\x1B[T".repeat(count)
};

/**
 * A helper function to clear the console based on a count of lines
 *
 * @param {string} current - The current console output to be cleared
 * @param {number} consoleWidth - The number of characters per line in the
 *   console
 */
export function clear(current: string, consoleWidth: number) {
  if (!consoleWidth) {
    return erase.line + cursor.to(0);
  }

  let rows = 0;
  const lines = current.split(/\r?\n/);
  for (let line of lines) {
    rows +=
      1 +
      Math.floor(Math.max([...stripAnsi(line)].length - 1, 0) / consoleWidth);
  }

  return erase.lines(rows);
}

/**
 * Removes ANSI escape codes from a string.
 *
 * @example
 * ```ts
 * const result = stripAnsi("Hello\\x1b[31mWorld\\x1b[0mAgain"); // "HelloWorldAgain"
 * ```
 * @param text - The text to strip ANSI codes from.
 * @returns The text with ANSI codes removed.
 *
 */
export function stripAnsi(text: string | number) {
  return String(text).replace(
    new RegExp(
      [
        String.raw`[\u001B\u009B][[\]()#;?]*(?:(?:(?:(?:;[-a-zA-Z\d\/#&.:=?%@~_]+)*|[a-zA-Z\d]+(?:;[-a-zA-Z\d\/#&.:=?%@~_]*)*)?\u0007)`,
        String.raw`(?:(?:\d{1,4}(?:;\d{0,4})*)?[\dA-PR-TZcf-nq-uy=><~]))`
      ].join("|"),
      "g"
    ),
    ""
  );
}

/**
 * Applies ANSI escape codes to a string.
 *
 * @remarks
 * Split text by /\\x1b[\[|\]][0-9;]*m/ and wrap non-ANSI parts with open/closing tags.
 * @example
 * ```ts
 * const result = wrapAnsi("Hello\\x1b[31mWorld\\x1b[0mAgain", "\\x1b[36m", "\\x1b[39");
 * console.log(result); // "\\x1b[36mHello\\x1b[39\\x1b[31mWorld\\x1b[0m\\x1b[36mAgain\\x1b[39"
 * ```
 * @param text - The text to apply ANSI codes to.
 * @param open - The opening ANSI code.
 * @param close - The closing ANSI code.
 * @returns The text with ANSI codes applied.
 *
 */
function wrapAnsi(text: string | number, open: string, close: string) {
  const str = String(text);
  const tokens = [] as string[];

  let last = 0;
  let match: RegExpExecArray | null;
  while ((match = /\\x1b[\[|\]][0-9;]*m/g.exec(str)) !== null) {
    if (match.index > last) tokens.push(str.slice(last, match.index));
    tokens.push(match[0]);
    last = match.index + match[0].length;
  }

  if (last < str.length) {
    tokens.push(str.slice(last));
  }

  let result = "";
  for (let i = 0; i < tokens.length; i++) {
    const seg = tokens[i]!;
    if (/^\\x1b[\[|\]][0-9;]*m$/.test(seg)) {
      result += seg;
      continue;
    }

    if (!seg) {
      continue;
    }

    result +=
      i > 0 &&
      /^\\x1b[\[|\]][0-9;]*m$/.test(tokens[i - 1]!) &&
      i + 1 < tokens.length &&
      /^\\x1b[\[|\]][0-9;]*m$/.test(tokens[i + 1]!)
        ? seg
        : `${open}${seg}${close}`;
  }

  return result;
}

/**
 * A function that applies a Reset text-style to provided console text.
 *
 * @param text - The console text to which the Reset text-style should be
 *   applied.
 * @returns A string with ANSI escape codes applied for Reset text-style, or the
 *   original text if the style is not supported in the current terminal.
 *
 */
export const reset = (
  text: string | number | boolean | null | undefined
): string => {
  try {
    if (text === undefined || text === null || text === "") {
      return "";
    }

    if (!isColorSupported) {
      return String(text);
    }

    if (colorSupportLevels.stdout === 1) {
      return wrapAnsi(String(text), "\x1b[0m", "\x1b[0m");
    } else if (colorSupportLevels.stdout === 2) {
      return wrapAnsi(String(text), "\x1b[0m", "\x1b[0m");
    }

    return wrapAnsi(String(text), "\x1b[0m", "\x1b[0m");
  } catch {
    return String(text);
  }
};

