/**
 * Write an error message to the console.
 *
 * @remarks
 * This function initializes the Powerlines environment configuration object.
 *
 * @param message - The message to write to the console.
 * @param header - An optional header to display above the message. If not
 *   provided, a default header based on the message type and variant will be
 *   used if defined in the theme configuration; otherwise, no header will be
 *   displayed.
 */
export function error(
  err: string | { message: string; stack?: string },
  header?: string
) {
  let message: string | undefined;

  if ((err as { message: string; stack?: string })?.message) {
    message = (err as { message: string; stack?: string }).message;
  } else {
    message = String(err);
  }

  if (
    env.STACKTRACE &&
    typeof err === "object" &&
    (err as { stack?: string })?.stack
  ) {
    message +=
      " \n\n" +
      (err as { stack: string }).stack
        .split("\n")
        .slice(1)
        .map(line => {
          const match = line.match(
            /at (?:(.+?)\s+\()?(?:(.+?):(\d+)(?::(\d+))?|([^)]+))\)?/
          );
          if (match) {
            const filePath = match[2] || match[5] || "<unknown>";
            return `at ${match[1] || "<anonymous>"} (${filePath === "<anonymous>" || filePath === "<unknown>" ? filePath : link(filePath, { text: `${filePath.replace(/^.*file:\/\//, "")}${match[3] ? `:${match[3]}${match[4] ? `:${match[4]}` : ""}` : ""}`, useTextWhenUnsupported: true })})`;
          }

          return line.trim();
        })
        .join("\n");
  }

  if (!message) {
    return;
  }

  const timestamp = `${textColors.message.footer.error(new Date().toLocaleDateString())} ${borderColors.message.outline.error("─")} ${textColors.message.footer.error(new Date().toLocaleTimeString())}`;

  writeLine(
    borderColors.message.outline.error("╭") +
      borderColors.message.outline.error("─".repeat(4)) +
      " " +
      borderColors.message.outline.error("✘") +
      " " +
      bold(textColors.message.header.error(header || "Error")) +
      " " +
      borderColors.message.outline.error(
        "─".repeat(Math.max(getTerminalSize().columns - 15, 0))
      ) +
      borderColors.message.outline.error("╮"),
    { consoleFn: console.error }
  );
  splitText(message, Math.max(getTerminalSize().columns - 18, 12)).forEach(
    line => {
      writeLine(
        borderColors.message.outline.error("│        ") +
          textColors.message.description.error(line) +
          " ".repeat(
            Math.max(
              getTerminalSize().columns - (stripAnsi(line).length + 10),
              0
            )
          ) +
          borderColors.message.outline.error("│"),
        { consoleFn: console.error }
      );
    }
  );
  writeLine(
    borderColors.message.outline.error("╰") +
      borderColors.message.outline.error(
        "─".repeat(
          Math.max(
            getTerminalSize().columns - 6 - (stripAnsi(timestamp).length + 2),
            0
          )
        )
      ) +
      " " +
      bold(textColors.message.footer.error(timestamp)) +
      " " +
      borderColors.message.outline.error("─".repeat(4)) +
      borderColors.message.outline.error("╯"),
    { consoleFn: console.error }
  );
}

/**
 * A type representing the width size of an item in the console.
 */
export type SizeToken =
  | "full"
  | "1/1"
  | "1/2"
  | "1/3"
  | "1/4"
  | "1/5"
  | "1/6"
  | "1/12"
  | "1/24"
  | "100%"
  | "50%"
  | "33.33%"
  | "25%"
  | "20%"
  | "10%"
  | "5%"
  | "2.5%";

/**
 * Determine if a value is a valid size token.
 *
 * @remarks
 * This function checks if the provided value is a valid size token, which can be one of the predefined strings representing common width sizes (e.g., "full", "1/2", "1/3", etc.) or percentage strings (e.g., "50%").
 * @param value - The value to check for being a valid size token.
 * @returns True if the value is a valid size token, false otherwise.
 *
 */
/**
 * Determines if the provided value is a valid size token.
 *
 * @param {any} value
 */
export function isSizeToken(value: any): value is SizeToken {
  if (
    [
      "full",
      "1/1",
      "1/2",
      "1/3",
      "1/4",
      "1/5",
      "1/6",
      "1/12",
      "1/24",
      "100%",
      "50%",
      "33.33%",
      "25%",
      "20%",
      "10%",
      "5%",
      "2.5%"
    ].includes(value)
  ) {
    return true;
  }
  return false;
}

/**
 * Calculate the width in characters based on the provided width size.
 *
 * @remarks
 * This function calculates the width in characters based on the provided width size, which can be a predefined string (e.g., "full", "1/2", "1/3", etc.) or a percentage string (e.g., "50%"). The calculation is based on the current width of the console (getTerminalSize().columns).
 * @param size - The width size to calculate. This can be a predefined string
 *   (e.g., "full", "1/2", "1/3", etc.) or a percentage string (e.g., "50%").
 * @returns The calculated width in characters.
 *
 */
export function calculateWidth(size: SizeToken): number {
  if (["full", "100%", "1/1"].includes(size)) {
    return getTerminalSize().columns;
  } else if (["1/2", "50%"].includes(size)) {
    return Math.round(getTerminalSize().columns / 2);
  } else if (["1/3", "33.33%"].includes(size)) {
    return Math.round(getTerminalSize().columns / 3);
  } else if (["1/4", "25%"].includes(size)) {
    return Math.round(getTerminalSize().columns / 4);
  } else if (["1/5", "20%"].includes(size)) {
    return Math.round(getTerminalSize().columns / 5);
  } else if (["1/6", "10%"].includes(size)) {
    return Math.round(getTerminalSize().columns / 6);
  } else if (["1/12", "5%"].includes(size)) {
    return Math.round(getTerminalSize().columns / 12);
  } else if (["1/24", "2.5%"].includes(size)) {
    return Math.round(getTerminalSize().columns / 24);
  } else {
    const match = size.match(/(\d+(\.\d+)?)%/);
    if (match) {
      return Math.round(
        (getTerminalSize().columns * parseFloat(match[1])) / 100
      );
    }

    throw new Error(`Invalid width size: ${size}`);
  }
} /**
 * The border options applied to table cells.
 */
export type BorderOption =
  | "primary"
  | "secondary"
  | "tertiary"
  | "none"
  | string;

/**
 * Options to customize the output of the {@link table} function.
 */
export interface TableOutputOptions {
  /**
   * Border variant for the table cell.
   *
   * @remarks
   * The border variant to use for the table cell. This determines the color and style of the border around the cell.
   *
   * @defaultValue primary
   */
  border?:
    | BorderOption
    | {
        top?: BorderOption;
        right?: BorderOption;
        bottom?: BorderOption;
        left?: BorderOption;
        topLeft?: BorderOption;
        topRight?: BorderOption;
        bottomLeft?: BorderOption;
        bottomRight?: BorderOption;
      };
  /**
   * Padding for the table cell.
   *
   * @remarks
   * The amount of padding (in spaces) to apply to the table cell. This value is applied to both the left and right sides of the cell. If not specified, the default table padding defined in the current theme configuration will be used.
   *
   * @defaultValue `1`
   */
  padding?: number;
  /**
   * Alignment for the table cell.
   *
   * @remarks
   * The alignment for the table cell. This determines how the text within the cell is aligned. If not specified, the default alignment is "left".
   *
   * @defaultValue left
   */
  align?: "left" | "right" | "center";
}

/**
 * Options for a specific table cell provided to the {@link table} function.
 */
export interface TableCellOptions extends TableOutputOptions {
  /**
   * The actual string value of the table cell.
   */
  value?: string;
  /**
   * Width of the table cell.
   *
   * @remarks
   * The width of the table cell (where 1 is a single character in the terminal). If not specified, the width will be determined based on the content of the cell and the available space in the console.
   */
  maxWidth: number | SizeToken | undefined;
}

/**
 * Options for a specific table row provided to the {@link table} function.
 */
export interface TableRowOptions extends TableOutputOptions {
  /**
   * The actual string values of the table row's cells.
   */
  values?: (string | TableCellOptions)[];
}

/**
 * Options for a specific table cell provided to the {@link table} function.
 */
export interface TableOptions extends TableOutputOptions {
  /**
   * The actual string values of the table's rows' cells.
   */
  values?: (string | TableCellOptions)[][];
}

/**
 * The height and width for a specific table/cell used internally in the {@link table} function.
 */
interface Dimensions {
  /**
   * The height of the row/cell (where 1 is a single line in the terminal).
   */
  height: number;
  /**
   * The width of the row/cell (where 1 is a single character in the terminal).
   */
  width: number;
}

/**
 * The resolved complete border styles for a table cell.
 */
interface TableCellBorder {
  /**
   * The top border style of the table cell.
   */
  top: string;
  /**
   * The bottom border style of the table cell.
   */
  bottom: string;
  /**
   * The right border style of the table cell.
   */
  right: string;
  /**
   * The left border style of the table cell.
   */
  left: string;
  /**
   * The top-left border style of the table cell.
   */
  topLeft: string;
  /**
   * The top-right border style of the table cell.
   */
  topRight: string;
  /**
   * The bottom-left border style of the table cell.
   */
  bottomLeft: string;
  /**
   * The bottom-right border style of the table cell.
   */
  bottomRight: string;
}

/**
 * The internal state of a formatted table cell in the {@link table} function.
 */
type TableCell = Required<Omit<TableCellOptions, "maxWidth" | "border">> &
  Dimensions & {
    border: TableCellBorder;
    maxWidth?: number;
  };

/**
 * Write a table to the console.
 *
 * @remarks
 * This function writes a table to the console, applying the appropriate padding as defined in the current theme configuration and wrapping as needed.
 *
 * @param options - Options to customize the table output.
 */
export function table(
  options:
    | TableOptions
    | TableRowOptions[]
    | TableCellOptions[][]
    | string[]
    | string[][]
) {
  if (
    !options ||
    (!Array.isArray(options) &&
      (typeof options !== "object" ||
        !options.values ||
        !Array.isArray(options.values) ||
        options.values.length === 0)) ||
    (Array.isArray(options) &&
      !options.every(
        item =>
          typeof item === "object" ||
          typeof item === "string" ||
          Array.isArray(item)
      ))
  ) {
    return;
  }

  let cells: TableCell[][] = [];
  const extractTableCell = (
    cell: string | TableCellOptions,
    columnIndex: number,
    rowLength: number,
    opts?: TableOutputOptions
  ): TableCell => {
    if (typeof cell === "string") {
      const borderOptions = opts?.border || "primary";

      let border = {} as TableCellBorder;
      if (typeof borderOptions === "object") {
        border = {
          top:
            borderOptions.top === "primary"
              ? borderColors.app.table.primary("─")
              : borderOptions.top === "secondary"
                ? borderColors.app.table.secondary("─")
                : borderOptions.top === "tertiary"
                  ? borderColors.app.table.tertiary("─")
                  : !borderOptions.top || borderOptions.top === "none"
                    ? ""
                    : borderOptions.top,
          bottom:
            borderOptions.bottom === "primary"
              ? borderColors.app.table.primary("─")
              : borderOptions.bottom === "secondary"
                ? borderColors.app.table.secondary("─")
                : borderOptions.bottom === "tertiary"
                  ? borderColors.app.table.tertiary("─")
                  : !borderOptions.bottom || borderOptions.bottom === "none"
                    ? ""
                    : borderOptions.bottom,
          left:
            borderOptions.left === "primary"
              ? borderColors.app.table.primary("│")
              : borderOptions.left === "secondary"
                ? borderColors.app.table.secondary("│")
                : borderOptions.left === "tertiary"
                  ? borderColors.app.table.tertiary("│")
                  : !borderOptions.left || borderOptions.left === "none"
                    ? ""
                    : borderOptions.left,
          right:
            borderOptions.right === "primary"
              ? borderColors.app.table.primary("│")
              : borderOptions.right === "secondary"
                ? borderColors.app.table.secondary("│")
                : borderOptions.right === "tertiary"
                  ? borderColors.app.table.tertiary("│")
                  : !borderOptions.right || borderOptions.right === "none"
                    ? ""
                    : borderOptions.right,
          topLeft:
            borderOptions.topLeft === "primary"
              ? borderColors.app.table.primary("┌")
              : borderOptions.topLeft === "secondary"
                ? borderColors.app.table.secondary("┌")
                : borderOptions.topLeft === "tertiary"
                  ? borderColors.app.table.tertiary("┌")
                  : !borderOptions.topLeft || borderOptions.topLeft === "none"
                    ? ""
                    : borderOptions.topLeft,
          topRight:
            borderOptions.topRight === "primary"
              ? borderColors.app.table.primary("┐")
              : borderOptions.topRight === "secondary"
                ? borderColors.app.table.secondary("┐")
                : borderOptions.topRight === "tertiary"
                  ? borderColors.app.table.tertiary("┐")
                  : !borderOptions.topRight || borderOptions.topRight === "none"
                    ? ""
                    : borderOptions.topRight,
          bottomLeft:
            borderOptions.bottomLeft === "primary"
              ? borderColors.app.table.primary("└")
              : borderOptions.bottomLeft === "secondary"
                ? borderColors.app.table.secondary("└")
                : borderOptions.bottomLeft === "tertiary"
                  ? borderColors.app.table.tertiary("└")
                  : !borderOptions.bottomLeft ||
                      borderOptions.bottomLeft === "none"
                    ? ""
                    : borderOptions.bottomLeft,
          bottomRight:
            borderOptions.bottomRight === "primary"
              ? borderColors.app.table.primary("┘")
              : borderOptions.bottomRight === "secondary"
                ? borderColors.app.table.secondary("┘")
                : borderOptions.bottomRight === "tertiary"
                  ? borderColors.app.table.tertiary("┘")
                  : !borderOptions.bottomRight ||
                      borderOptions.bottomRight === "none"
                    ? ""
                    : borderOptions.bottomRight
        };
      } else {
        border.top =
          borderOptions === "primary"
            ? borderColors.app.table.primary("─")
            : borderOptions === "secondary"
              ? borderColors.app.table.secondary("─")
              : borderOptions === "tertiary"
                ? borderColors.app.table.tertiary("─")
                : !borderOptions || borderOptions === "none"
                  ? ""
                  : borderOptions;
        border.bottom =
          borderOptions === "primary"
            ? borderColors.app.table.primary("─")
            : borderOptions === "secondary"
              ? borderColors.app.table.secondary("─")
              : borderOptions === "tertiary"
                ? borderColors.app.table.tertiary("─")
                : !borderOptions || borderOptions === "none"
                  ? ""
                  : borderOptions;
        border.left =
          borderOptions === "primary"
            ? borderColors.app.table.primary("│")
            : borderOptions === "secondary"
              ? borderColors.app.table.secondary("│")
              : borderOptions === "tertiary"
                ? borderColors.app.table.tertiary("│")
                : !borderOptions || borderOptions === "none"
                  ? ""
                  : borderOptions;
        border.right =
          borderOptions === "primary"
            ? borderColors.app.table.primary("│")
            : borderOptions === "secondary"
              ? borderColors.app.table.secondary("│")
              : borderOptions === "tertiary"
                ? borderColors.app.table.tertiary("│")
                : !borderOptions || borderOptions === "none"
                  ? ""
                  : borderOptions;
        border.topLeft =
          borderOptions === "primary"
            ? borderColors.app.table.primary("┌")
            : borderOptions === "secondary"
              ? borderColors.app.table.secondary("┌")
              : borderOptions === "tertiary"
                ? borderColors.app.table.tertiary("┌")
                : !borderOptions || borderOptions === "none"
                  ? ""
                  : borderOptions;
        border.topRight =
          borderOptions === "primary"
            ? borderColors.app.table.primary("┐")
            : borderOptions === "secondary"
              ? borderColors.app.table.secondary("┐")
              : borderOptions === "tertiary"
                ? borderColors.app.table.tertiary("┐")
                : !borderOptions || borderOptions === "none"
                  ? ""
                  : borderOptions;
        border.bottomLeft =
          borderOptions === "primary"
            ? borderColors.app.table.primary("└")
            : borderOptions === "secondary"
              ? borderColors.app.table.secondary("└")
              : borderOptions === "tertiary"
                ? borderColors.app.table.tertiary("└")
                : !borderOptions || borderOptions === "none"
                  ? ""
                  : borderOptions;
        border.bottomRight =
          borderOptions === "primary"
            ? borderColors.app.table.primary("┘")
            : borderOptions === "secondary"
              ? borderColors.app.table.secondary("┘")
              : borderOptions === "tertiary"
                ? borderColors.app.table.tertiary("┘")
                : !borderOptions || borderOptions === "none"
                  ? ""
                  : borderOptions;
      }

      const padding =
        Math.max(0, opts?.padding ?? 1) *
        (columnIndex === 0 || columnIndex === rowLength - 1 ? 2 : 1);
      const value = cell ?? "";
      const width = stripAnsi(value).length + padding * 2;

      return {
        value,
        height: 1,
        width,
        border,
        padding,
        align: opts?.align || "left"
      };
    } else {
      const borderOptions = cell.border || opts?.border || "primary";

      let border = {} as TableCellBorder;
      if (typeof borderOptions === "object") {
        border = {
          top:
            borderOptions.top === "primary"
              ? borderColors.app.table.primary("─")
              : borderOptions.top === "secondary"
                ? borderColors.app.table.secondary("─")
                : borderOptions.top === "tertiary"
                  ? borderColors.app.table.tertiary("─")
                  : !borderOptions.top || borderOptions.top === "none"
                    ? ""
                    : borderOptions.top,
          bottom:
            borderOptions.bottom === "primary"
              ? borderColors.app.table.primary("─")
              : borderOptions.bottom === "secondary"
                ? borderColors.app.table.secondary("─")
                : borderOptions.bottom === "tertiary"
                  ? borderColors.app.table.tertiary("─")
                  : !borderOptions.bottom || borderOptions.bottom === "none"
                    ? ""
                    : borderOptions.bottom,
          left:
            borderOptions.left === "primary"
              ? borderColors.app.table.primary("│")
              : borderOptions.left === "secondary"
                ? borderColors.app.table.secondary("│")
                : borderOptions.left === "tertiary"
                  ? borderColors.app.table.tertiary("│")
                  : !borderOptions.left || borderOptions.left === "none"
                    ? ""
                    : borderOptions.left,
          right:
            borderOptions.right === "primary"
              ? borderColors.app.table.primary("│")
              : borderOptions.right === "secondary"
                ? borderColors.app.table.secondary("│")
                : borderOptions.right === "tertiary"
                  ? borderColors.app.table.tertiary("│")
                  : !borderOptions.right || borderOptions.right === "none"
                    ? ""
                    : borderOptions.right,
          topLeft:
            borderOptions.topLeft === "primary"
              ? borderColors.app.table.primary("┌")
              : borderOptions.topLeft === "secondary"
                ? borderColors.app.table.secondary("┌")
                : borderOptions.topLeft === "tertiary"
                  ? borderColors.app.table.tertiary("┌")
                  : !borderOptions.topLeft || borderOptions.topLeft === "none"
                    ? ""
                    : borderOptions.topLeft,
          topRight:
            borderOptions.topRight === "primary"
              ? borderColors.app.table.primary("┐")
              : borderOptions.topRight === "secondary"
                ? borderColors.app.table.secondary("┐")
                : borderOptions.topRight === "tertiary"
                  ? borderColors.app.table.tertiary("┐")
                  : !borderOptions.topRight || borderOptions.topRight === "none"
                    ? ""
                    : borderOptions.topRight,
          bottomLeft:
            borderOptions.bottomLeft === "primary"
              ? borderColors.app.table.primary("└")
              : borderOptions.bottomLeft === "secondary"
                ? borderColors.app.table.secondary("└")
                : borderOptions.bottomLeft === "tertiary"
                  ? borderColors.app.table.tertiary("└")
                  : !borderOptions.bottomLeft ||
                      borderOptions.bottomLeft === "none"
                    ? ""
                    : borderOptions.bottomLeft,
          bottomRight:
            borderOptions.bottomRight === "primary"
              ? borderColors.app.table.primary("┘")
              : borderOptions.bottomRight === "secondary"
                ? borderColors.app.table.secondary("┘")
                : borderOptions.bottomRight === "tertiary"
                  ? borderColors.app.table.tertiary("┘")
                  : !borderOptions.bottomRight ||
                      borderOptions.bottomRight === "none"
                    ? ""
                    : borderOptions.bottomRight
        };
      } else {
        border.top =
          borderOptions === "primary"
            ? borderColors.app.table.primary("─")
            : borderOptions === "secondary"
              ? borderColors.app.table.secondary("─")
              : borderOptions === "tertiary"
                ? borderColors.app.table.tertiary("─")
                : !borderOptions || borderOptions === "none"
                  ? ""
                  : borderOptions;
        border.bottom =
          borderOptions === "primary"
            ? borderColors.app.table.primary("─")
            : borderOptions === "secondary"
              ? borderColors.app.table.secondary("─")
              : borderOptions === "tertiary"
                ? borderColors.app.table.tertiary("─")
                : !borderOptions || borderOptions === "none"
                  ? ""
                  : borderOptions;
        border.left =
          borderOptions === "primary"
            ? borderColors.app.table.primary("│")
            : borderOptions === "secondary"
              ? borderColors.app.table.secondary("│")
              : borderOptions === "tertiary"
                ? borderColors.app.table.tertiary("│")
                : !borderOptions || borderOptions === "none"
                  ? ""
                  : borderOptions;
        border.right =
          borderOptions === "primary"
            ? borderColors.app.table.primary("│")
            : borderOptions === "secondary"
              ? borderColors.app.table.secondary("│")
              : borderOptions === "tertiary"
                ? borderColors.app.table.tertiary("│")
                : !borderOptions || borderOptions === "none"
                  ? ""
                  : borderOptions;
        border.topLeft =
          borderOptions === "primary"
            ? borderColors.app.table.primary("┌")
            : borderOptions === "secondary"
              ? borderColors.app.table.secondary("┌")
              : borderOptions === "tertiary"
                ? borderColors.app.table.tertiary("┌")
                : !borderOptions || borderOptions === "none"
                  ? ""
                  : borderOptions;
        border.topRight =
          borderOptions === "primary"
            ? borderColors.app.table.primary("┐")
            : borderOptions === "secondary"
              ? borderColors.app.table.secondary("┐")
              : borderOptions === "tertiary"
                ? borderColors.app.table.tertiary("┐")
                : !borderOptions || borderOptions === "none"
                  ? ""
                  : borderOptions;
        border.bottomLeft =
          borderOptions === "primary"
            ? borderColors.app.table.primary("└")
            : borderOptions === "secondary"
              ? borderColors.app.table.secondary("└")
              : borderOptions === "tertiary"
                ? borderColors.app.table.tertiary("└")
                : !borderOptions || borderOptions === "none"
                  ? ""
                  : borderOptions;
        border.bottomRight =
          borderOptions === "primary"
            ? borderColors.app.table.primary("┘")
            : borderOptions === "secondary"
              ? borderColors.app.table.secondary("┘")
              : borderOptions === "tertiary"
                ? borderColors.app.table.tertiary("┘")
                : !borderOptions || borderOptions === "none"
                  ? ""
                  : borderOptions;
      }

      const padding = Math.max(0, cell.padding ?? opts?.padding ?? 1);
      const value = cell.value ?? "";
      const width = stripAnsi(value).length + padding * 2;
      const maxWidth = cell.maxWidth
        ? typeof cell.maxWidth === "number"
          ? cell.maxWidth
          : calculateWidth(cell.maxWidth)
        : undefined;

      return {
        value,
        height: 1,
        width,
        maxWidth,
        border,
        padding,
        align: cell.align || opts?.align || "left"
      };
    }
  };

  let colMaxWidths = [] as (number | undefined)[];
  if (Array.isArray(options)) {
    if (
      options.every(
        row =>
          typeof row === "string" ||
          (typeof row === "object" && !Array.isArray(row) && !("values" in row))
      )
    ) {
      cells.push(
        options.map((cell, index) =>
          extractTableCell(
            cell as string | TableCellOptions,
            index,
            options.length
          )
        )
      );
    } else {
      cells.push(
        ...options.map(row =>
          Array.isArray(row)
            ? row.reduce((cellRow, cell, index) => {
                if (colMaxWidths.length <= index) {
                  colMaxWidths.push(undefined);
                }
                const newCell = extractTableCell(cell, index, row.length);
                if (
                  newCell.maxWidth &&
                  (!colMaxWidths[index] ||
                    newCell.maxWidth < colMaxWidths[index]!)
                ) {
                  colMaxWidths[index] = newCell.maxWidth;
                }
                cellRow.push(newCell);
                return cellRow;
              }, [] as TableCell[])
            : ((row as TableRowOptions).values?.reduce(
                (cellRow, cell, index) => {
                  if (colMaxWidths.length <= index) {
                    colMaxWidths.push(undefined);
                  }
                  const newCell = extractTableCell(
                    cell,
                    index,
                    (row as TableRowOptions).values?.length ?? 1,
                    row as TableRowOptions
                  );
                  if (
                    newCell.maxWidth &&
                    (!colMaxWidths[index] ||
                      newCell.maxWidth < colMaxWidths[index]!)
                  ) {
                    colMaxWidths[index] = newCell.maxWidth;
                  }
                  cellRow.push(newCell);
                  return cellRow;
                },
                [] as TableCell[]
              ) ?? [])
        )
      );
    }
  } else {
    cells.push(
      ...options.values!.map(row =>
        Array.isArray(row)
          ? row.reduce((cellRow, cell, index) => {
              if (colMaxWidths.length <= index) {
                colMaxWidths.push(undefined);
              }
              const newCell = extractTableCell(cell, index, row.length);
              if (
                newCell.maxWidth &&
                (!colMaxWidths[index] ||
                  newCell.maxWidth < colMaxWidths[index]!)
              ) {
                colMaxWidths[index] = newCell.maxWidth;
              }
              cellRow.push(newCell);
              return cellRow;
            }, [] as TableCell[])
          : ((row as TableRowOptions).values?.reduce((cellRow, cell, index) => {
              if (colMaxWidths.length <= index) {
                colMaxWidths.push(undefined);
              }
              const newCell = extractTableCell(
                cell,
                index,
                (row as TableRowOptions).values?.length ?? 1,
                options
              );
              if (
                newCell.maxWidth &&
                (!colMaxWidths[index] ||
                  newCell.maxWidth < colMaxWidths[index]!)
              ) {
                colMaxWidths[index] = newCell.maxWidth;
              }
              cellRow.push(newCell);
              return cellRow;
            }, [] as TableCell[]) ?? [])
      )
    );
  }
  cells = cells.filter(row => row.length > 0);
  if (cells.length === 0) {
    return;
  }

  cells.forEach(row =>
    row.forEach((cell, index) => {
      if (colMaxWidths[index] && cell.maxWidth !== colMaxWidths[index]!) {
        cell.maxWidth = colMaxWidths[index]!;
      }
    })
  );

  // Calculate table dimensions
  let colWidths = [] as number[];
  let rowDims = [] as Dimensions[];

  const calculateRowDimensions = () => {
    colWidths = [];
    return cells.reduce((dims, row) => {
      dims.push(
        row.reduce(
          (dim, cell, index) => {
            dim.width += cell.width;
            if (cell.height > dim.height) {
              dim.height = cell.height;
            }
            if (!colWidths[index] || cell.width > colWidths[index]!) {
              colWidths[index] = cell.width;
            }

            return dim;
          },
          { width: 0, height: 0 } as Dimensions
        )
      );

      return dims;
    }, [] as Dimensions[]);
  };

  let recalculate!: boolean;
  do {
    recalculate = false;
    rowDims = calculateRowDimensions();

    if (
      !recalculate &&
      colWidths.some(
        (colWidth, index) =>
          colMaxWidths[index] && colWidth > colMaxWidths[index]!
      )
    ) {
      (
        colWidths
          .map((colWidth, index) =>
            colMaxWidths[index] && colWidth > colMaxWidths[index]!
              ? index
              : undefined
          )
          .filter(colWidth => colWidth !== undefined) as number[]
      ).forEach(index => {
        cells.forEach(row => {
          const cell = row[index]!;
          if (colMaxWidths[index] && cell.width > colMaxWidths[index]) {
            const lines = splitText(
              cell.value,
              colMaxWidths[index] - cell.padding * 2
            );

            cell.value = lines.join("\n");
            cell.height = lines.length;
            cell.width =
              Math.max(...lines.map(line => stripAnsi(line).length)) +
              cell.padding * 2;

            recalculate = true;
          }
        });
      });
    }

    rowDims.forEach((row, rowIndex) => {
      if (
        !recalculate &&
        row.width > Math.max(getTerminalSize().columns - 0, 0)
      ) {
        const cell = cells[rowIndex]!.reduce((largestCell, cell) => {
          if (cell.width > largestCell.width) {
            return cell;
          }
          return largestCell;
        }, cells[rowIndex]![0]!);

        const lines = splitText(
          cell.value,
          Math.min(
            Math.max(
              getTerminalSize().columns -
                0 -
                (row.width - (cell.width - cell.padding * 2)),
              0
            ),
            cell.maxWidth ?? Number.POSITIVE_INFINITY
          )
        );

        cell.value = lines.join("\n");
        cell.height = lines.length;
        cell.width =
          Math.max(...lines.map(line => stripAnsi(line).length)) +
          cell.padding * 2;

        recalculate = true;
      }
    });

    if (
      !recalculate &&
      colWidths.reduce((a, b) => a + b, 0) >
        Math.max(getTerminalSize().columns - 0, 0)
    ) {
      let colIndex = 0;
      const cell = cells.reduce((ret, row) => {
        return row.reduce((largest, current, index) => {
          if (largest.width < current.width) {
            colIndex = index;
            return current;
          }
          return largest;
        }, ret);
      }, cells[0]![0]!);

      const lines = splitText(
        cell.value,
        Math.min(
          Math.max(
            getTerminalSize().columns -
              0 -
              colWidths
                .filter((_, i) => i !== colIndex)
                .reduce((a, b) => a + b, 0) -
              cell.padding * 2,
            0
          ),
          cell.maxWidth ?? Number.POSITIVE_INFINITY
        )
      );

      cell.value = lines.join("\n");
      cell.height = lines.length;
      cell.width =
        Math.max(...lines.map(line => stripAnsi(line).length)) +
        cell.padding * 2;

      recalculate = true;
    }
  } while (recalculate);

  // Render table
  cells.forEach((row, rowIndex) => {
    const outputs = [] as string[][];
    row.forEach((cell, colIndex) => {
      const lines = cell.value.split("\n");
      while (lines.length < rowDims[rowIndex]!.height) {
        lines.push("");
      }

      outputs.push(
        lines.map(line => {
          let paddedContent = "";
          switch (cell.align) {
            case "right":
              paddedContent =
                " ".repeat(
                  Math.max(
                    colWidths[colIndex] - stripAnsi(line).length - cell.padding,
                    0
                  )
                ) +
                line +
                " ".repeat(cell.padding);
              break;
            case "center":
              const leftPadding = Math.floor(
                (colWidths[colIndex] - stripAnsi(line).length - cell.padding) /
                  2
              );
              const rightPadding =
                colWidths[colIndex] - stripAnsi(line).length - leftPadding;
              paddedContent =
                " ".repeat(leftPadding) + line + " ".repeat(rightPadding);
              break;
            case "left":
            default:
              paddedContent =
                " ".repeat(cell.padding) +
                line +
                " ".repeat(
                  Math.max(
                    colWidths[colIndex] - stripAnsi(line).length - cell.padding,
                    0
                  )
                );
              break;
          }

          if (colIndex === row.length - 1) {
            return cell.border.left + paddedContent + cell.border.right;
          } else {
            return cell.border.left + paddedContent;
          }
        })
      );
    });

    for (let index = 0; index < rowDims[rowIndex]!.height; index++) {
      writeLine(outputs.map(output => output[index] ?? "").join(""));
    }
  });
}

/**
 * Format a string with blockquote styling for display in console.
 *
 * @param text - The text to format with blockquote styling.
 * @returns The formatted string with blockquote styling.
 *
 */
export function blockquote(text?: string | number | boolean | null): string {
  if (text === undefined || text === null || text === "") {
    return "";
  }

  const lines = splitText(
    String(text),
    Math.max(getTerminalSize().columns, 20) - 6
  );

  return lines
    .map(
      line =>
        `${borderColors.app.blockquote.primary(isUnicodeSupported() ? "│" : "|")}   ${italic(line)} `
    )
    .join("\n");
}

/**
 * Format a source code string for display in console.
 *
 * @param text - The source code text to format with code styling.
 * @returns The formatted string with code styling.
 *
 */
export function code(
  text?: string | number | boolean | null,
  language?: string
): string {
  if (text === undefined || text === null || text === "") {
    return "";
  }

  const lines = splitText(
    String(text),
    Math.max(getTerminalSize().columns, 20)
  );

  return ` ${borderColors.app.divider.primary("─".repeat(4))}${language ? ` ${borderColors.app.divider.primary(language)} ` : ""}${borderColors.app.divider.primary("─".repeat(getTerminalSize().columns - (language ? language.length + 2 : 0) - 5))} \n${lines.map((line, index) => ` ${" ".repeat(String(lines.length).length - String(index + 1).length)}${textColors.body.tertiary(index + 1)} ${textColors.body.primary(line)}`).join("\n")}`;
}

/**
 * Format a string with inline code styling for display in console.
 *
 * @param text - The text to format with inline code styling.
 * @returns The formatted string with inline code styling.
 *
 */
export function inlineCode(text?: string | number | boolean | null): string {
  if (text === undefined || text === null || text === "") {
    return "";
  }

  return inverse(`${text}`);
}
